Here's a Python script that demonstrates hash vulnerability assessment using precomputed hash tables:

```python
import hashlib
import os
import csv

# Generate optimized lookup structures for common password dictionaries
def generate_hash_table(dictionary_file):
    hash_table = {}
    with open(dictionary_file, 'r') as file:
        for line in file:
            password = line.strip()
            hash_value = hashlib.md5(password.encode()).hexdigest()
            if hash_value not in hash_table:
                hash_table[hash_value] = password
    return hash_table

# Implement hash comparison mechanisms for SHA-1 and MD5 algorithms
def compare_hash(hash_value, hash_table):
    if hash_value in hash_table:
        return hash_table[hash_value]
    else:
        return None

# Output statistical matches for vulnerability reporting
def report_vulnerability(matches):
    if matches:
        print("Vulnerability found! Matching passwords:")
        for match in matches:
            print(match)

# Salt detection routines
def detect_salt(hash_value):
    if len(hash_value) > 32:
        return True
    else:
        return False

# Memory-efficient storage methods
def save_hash_table(hash_table, output_file):
    with open(output_file, 'w', newline='') as file:
        writer = csv.writer(file)
        for hash_value, password in hash_table.items():
            writer.writerow([hash_value, password])

# Compliance testing framework to evaluate organizational password policy effectiveness
def test_password_policy(password, hash_table):
    hash_value = hashlib.md5(password.encode()).hexdigest()
    match = compare_hash(hash_value, hash_table)
    if match:
        return "Weak password: " + match
    elif detect_salt(hash_value):
        return "Salted password detected"
    else:
        return "Password meets security guidelines"

# Main function
def main():
    dictionary_file = 'passwords.txt'
    hash_table = generate_hash_table(dictionary_file)
    save_hash_table(hash_table, 'hash_table.csv')

    password = input("Enter password to test: ")
    result = test_password_policy(password, hash_table)
    print(result)

if __name__ == "__main__":
    main()
```

This script includes functions for generating a hash table from a common password dictionary, comparing hash values, reporting vulnerabilities, detecting salt, and testing password policy compliance. The main function demonstrates how to use these functions to evaluate the security of a given password against historical cryptographic weaknesses.

